const tabId = 845789509;

const scheduleAnalysis = await browserjs(tabId, async () => {
  const url = "https://statsapi.mlb.com/api/v1/schedule?sportId=1&season=2026&gameType=R&hydrate=team,venue";
  const res = await fetch(url);
  const data = await res.json();

  // 30 teams and their primary venues
  // Let's filter dates between 2026-06-01 and 2026-08-31
  const summerDates = data.dates.filter(d => d.date >= "2026-06-01" && d.date <= "2026-08-31");

  // Count games by venue in summer
  const venueGameCounts = {};
  const gamesByDate = {};

  for (const d of summerDates) {
    gamesByDate[d.date] = [];
    for (const g of d.games || []) {
      const vName = g.venue?.name;
      const vId = g.venue?.id;
      const hTeam = g.teams?.home?.team?.name;
      const aTeam = g.teams?.away?.team?.name;
      const hId = g.teams?.home?.team?.id;
      const aId = g.teams?.away?.team?.id;

      venueGameCounts[vName] = (venueGameCounts[vName] || 0) + 1;
      gamesByDate[d.date].push({
        date: d.date,
        gamePk: g.gamePk,
        venueId: vId,
        venue: vName,
        homeTeam: hTeam,
        homeId: hId,
        awayTeam: aTeam,
        awayId: aId,
        isDodgers: hId === 119 || aId === 119, // Ohtani
        isYankees: hId === 147 || aId === 147, // Judge
        isBraves: hId === 144 || aId === 144, // Acuna
      });
    }
  }

  return {
    totalSummerDays: summerDates.length,
    venueGameCounts,
    dateKeys: Object.keys(gamesByDate).slice(0, 10)
  };
});

console.log("Summer days:", scheduleAnalysis.totalSummerDays);
console.log("Venue game counts:", Object.keys(scheduleAnalysis.venueGameCounts).length, scheduleAnalysis.venueGameCounts);

