    "Globe Life Field": { team: "Texas Rangers", city: "Arlington, TX", lat: 32.7473, lon: -97.0838, airport: "DFW" },
    "Rogers Centre": { team: "Toronto Blue Jays", city: "Toronto, ON", lat: 43.6414, lon: -79.3894, airport: "YYZ" },
