    const v1 = targetVenues[v1Name];
    const v2 = targetVenues[v2Name];
    const R = 3958.8;
    const dLat = (v2.lat - v1.lat) * Math.PI / 180;
    const dLon = (v2.lon - v1.lon) * Math.PI / 180;
    const a = Math.sin(dLat/2) * Math.sin(dLat/2) +
              Math.cos(v1.lat * Math.PI / 180) * Math.cos(v2.lat * Math.PI / 180) *
              Math.sin(dLon/2) * Math.sin(dLon/2);
    return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
  }

  // Collect all games between 2026-06-01 and 2026-08-31
  const games = [];
  for (const d of data.dates || []) {
    if (d.date < "2026-06-01" || d.date > "2026-08-31") continue;
    for (const g of d.games || []) {
      const v = g.venue?.name;
      if (!targetVenues[v]) continue;

      const homeTeam = g.teams?.home?.team?.name;
      const awayTeam = g.teams?.away?.team?.name;
      const homeId = g.teams?.home?.team?.id;
      const awayId = g.teams?.away?.team?.id;

      const stars = [];
      if (homeId === 119 || awayId === 119) stars.push("Shohei Ohtani (LAD)");
      if (homeId === 147 || awayId === 147) stars.push("Aaron Judge (NYY)");
      if (homeId === 144 || awayId === 144) stars.push("Ronald Acuña Jr. (ATL)");

      games.push({
        date: d.date,
        gamePk: g.gamePk,
        venue: v,
        homeTeam,
        awayTeam,
        homeId,
        awayId,
        stars,
        time: g.gameDate
      });
    }
  }

  // Organize by venue: venue -> list of games sorted by date
  const venueGames = {};
  for (const v of Object.keys(targetVenues)) venueGames[v] = [];
  for (const g of games) venueGames[g.venue].push(g);

  // Let's inspect when Dodger Stadium, Yankee Stadium, Truist Park have games featuring the stars
  return {
    gamesCount: games.length,
    dodgerGames: venueGames["UNIQLO Field at Dodger Stadium"].map(g => ({ date: g.date, matchup: `${g.awayTeam} at ${g.homeTeam}`, stars: g.stars })),
    yankeeGames: venueGames["Yankee Stadium"].map(g => ({ date: g.date, matchup: `${g.awayTeam} at ${g.homeTeam}`, stars: g.stars })),
    truistGames: venueGames["Truist Park"].map(g => ({ date: g.date, matchup: `${g.awayTeam} at ${g.homeTeam}`, stars: g.stars }))
  };
});

console.log("Dodger Games:", solver.dodgerGames.length, solver.dodgerGames.slice(0, 5));
console.log("Yankee Games:", solver.yankeeGames.length, solver.yankeeGames.slice(0, 5));
console.log("Truist Games:", solver.truistGames.length, solver.truistGames.slice(0, 5));
","cwd":null}

