    "Oriole Park at Camden Yards": { team: "Baltimore Orioles", city: "Baltimore, MD", lat: 39.2838, lon: -76.6217, airport: "BWI" },
    "Fenway Park": { team: "Boston Red Sox", city: "Boston, MA", lat: 42.3467, lon: -71.0972, airport: "BOS" },
    "Wrigley Field": { team: "Chicago Cubs", city: "Chicago, IL", lat: 41.9484, lon: -87.6553, airport: "ORD" },
    "Great American Ball Park": { team: "Cincinnati Reds", city: "Cincinnati, OH", lat: 39.0979, lon: -84.5082, airport: "CVG" },
    "Progressive Field": { team: "Cleveland Guardians", city: "Cleveland, OH", lat: 41.4962, lon: -81.6852, airport: "CLE" },
    "Coors Field": { team: "Colorado Rockies", city: "Denver, CO", lat: 39.7559, lon: -104.9942, airport: "DEN" },
    "Comerica Park": { team: "Detroit Tigers", city: "Detroit, MI", lat: 42.3390, lon: -83.0485, airport: "DTW" },
    "Daikin Park": { team: "Houston Astros", city: "Houston, TX", lat: 29.7573, lon: -95.3555, airport: "IAH" },
    "Kauffman Stadium": { team: "Kansas City Royals", city: "Kansas City, MO", lat: 39.0517, lon: -94.4803, airport: "MCI" },
    "UNIQLO Field at Dodger Stadium": { team: "Los Angeles Dodgers", city: "Los Angeles, CA", lat: 34.0739, lon: -118.2400, airport: "LAX" },
    "Nationals Park": { team: "Washington Nationals", city: "Washington, DC", lat: 38.8730, lon: -77.0074, airport: "DCA" },
    "Citi Field": { team: "New York Mets", city: "New York, NY", lat: 40.7571, lon: -73.8458, airport: "LGA" }
  };

