  for (const g of allSummerGames) {
    if (!gamesByDate[g.date]) gamesByDate[g.date] = [];
    gamesByDate[g.date].push(g);
  }
  const dateList = Object.keys(gamesByDate).sort();

  // Let's test a beam search or heuristic search to find paths visiting 30 unique venues
  // State: { currentVenue, visitedSet (bitmask or Set), path: [games], totalDist, starCount }
  // To avoid huge states, let's use beam search keeping top K best partial paths at each step.
  // Each step advances date by 1 or 2 days (or maybe same day if double-header in same city, but usually 1 game per day).

  // Let's see how many days we have: 89 days.
  // We need to pick 30 games across 89 days, visiting 30 distinct venues.
  // Let's run a randomized greedy / simulated annealing / local search or beam search.

  function findTour() {
    // Let's try starting at various venues and dates
    let bestTour = null;
    let bestScore = -Infinity;

    // Try 50 random starts or systematic starts
    for (let attempt = 0; attempt < 200; attempt++) {
      // Pick a random start date between June 1 and July 1
      const startIdx = Math.floor(Math.random() * 25);
      const visited = new Set();
      const path = [];
      let currentVenue = null;
      let totalDist = 0;
      let starsTotal = 0;

      let curDateIdx = startIdx;
      while (curDateIdx < dateList.length && visited.size < 30) {
        const d = dateList[curDateIdx];
        const dayGames = gamesByDate[d] || [];

        // Find candidate games where venue is not visited yet
        const candidates = dayGames.filter(g => !visited.has(g.venue));
        if (candidates.length === 0) {
          curDateIdx++;
          continue;
        }

        // Score candidates based on distance from currentVenue and whether it has stars
        candidates.sort((a, b) => {
          let scoreA = 0;
          let scoreB = 0;
          if (a.stars.length > 0) scoreA += 500;
          if (b.stars.length > 0) scoreB += 500;

          if (currentVenue) {
            const dA = dist(currentVenue, a.venue);
            const dB = dist(currentVenue, b.venue);
            scoreA -= dA;
            scoreB -= dB;
          }
          return scoreB - scoreA; // descending
        });

        // Pick one of the top candidates (with some randomness for variety across attempts)
        const pickIdx = Math.min(candidates.length - 1, Math.floor(Math.random() * Math.min(3, candidates.length)));
        const chosen = candidates[pickIdx];

        if (currentVenue) {
          totalDist += dist(currentVenue, chosen.venue);
        }
        visited.add(chosen.venue);
        path.push(chosen);
        currentVenue = chosen.venue;
        starsTotal += chosen.stars.length;

        // Advance by 1 or 2 days
        curDateIdx += 1;
      }

      if (visited.size === 30) {
        // Score: more stars is better, less distance is better
        const score = starsTotal * 500 - totalDist;
        if (score > bestScore) {
          bestScore = score;
          bestTour = {
            path,
            totalDist: Math.round(totalDist),
            starsTotal,
            durationDays: (new Date(path[29].date) - new Date(path[0].date)) / (1000 * 60 * 60 * 24) + 1,
            startDate: path[0].date,
            endDate: path[29].date
          };
        }
      }
    }

    return bestTour;
  }

  const tour = findTour();
  return { tour };
});

console.log("Search result:", searchResult);

