      candidates.sort((a, b) => {
        let dA = currentVenue ? dist(currentVenue, a.venue) : 0;
        let dB = currentVenue ? dist(currentVenue, b.venue) : 0;

        // Bonus if stars
        let costA = dA - (a.stars.length > 0 ? 150 : 0);
        let costB = dB - (b.stars.length > 0 ? 150 : 0);
        return costA - costB;
      });

      // Greedily pick the best candidate (or 2nd best with small probability)
      const pickIdx = (Math.random() < 0.75 || candidates.length === 1) ? 0 : 1;
